        'title' => "Lord, We Pray Thee, Send Forth Reapers!",
        'lyrics' => "1. Far and near the fields are teeming
        With the waves of ripened grain;
        Far and near their gold is gleaming
        O\'er the sunny slope and plain.
        
        2. Lord, we pray Thee, send forth reapers!
        Hear us, while to Thee we cry;
        Send them now the sheaves to gather,
        Ere the harvest-time pass by.
        
        3. Send them forth with morn\'s first beaming,
        Send them in the noontide\'s glare;
        When the sun\'s last rays are gleaming,
        Bid them gather everywhere.
        
        4. Hasten now, the grain is bending,
        Gather now the sheaves of gold;
        Homeward then at evening wending,
        Thou shall come with joy untold.",
    ],
    [
        'number' => "398",
        'title' => "God Make My Life A Little Light",
        'lyrics' => "1. God make my life a little light
        Within the world to glow;
        A little flame that burneth bright,
        Wherever I may go.
        
        2. God make my life a little flower
        That giveth joy to all,
        Content to bloom in native bower,
        Although the place be small.
        
        3. God make my life a little song
        That comforteth the sad,
        That helpeth others to be strong,
        And makes the singer glad.
        
        4. God make my life a little staff,
        Whereon the weak may rest;
        That so what health and strength I have
        May serve my neighbours best.
        
        5. God make my life a little hymn
        Of tenderness and praise;
        Of faith - that never waxeth dim,
        In all His wondrous ways.",
